package com.mvt.backApp.security.service;
import com.mvt.backApp.security.model.AuthenticatedUser;import com.mvt.backApp.user.entity.Permission;import com.mvt.backApp.user.entity.User;import com.mvt.backApp.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.core.userdetails.UsernameNotFoundException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.stream.Stream;
@Service @RequiredArgsConstructor public class CustomUserDetailsService implements UserDetailsService{private final UserRepository userRepository;@Override @Transactional(readOnly=true)public UserDetails loadUserByUsername(String email){User u=userRepository.findByEmail(email).orElseThrow(()->new UsernameNotFoundException("User not found"));if(u.getRole()==null)throw new UsernameNotFoundException("User role is not assigned");var authorities=Stream.concat(u.getRole().getPermissions().stream(),u.getDirectPermissions().stream()).map(Permission::getName).distinct().sorted().map(SimpleGrantedAuthority::new).toList();return new AuthenticatedUser(u.getId(),u.getEmail(),u.getPasswordHash(),u.getRole().getName(),authorities,u.isActive()&&!u.isDeleted()&&u.isEmailVerified());}}
